/**
 * Installing: the hero and the end of the page show the MCP server's URL and a "How to use"
 * button that opens every agent's steps in a dialog; the same steps are in the full panel in
 * "How it works". Every command comes from content/site.ts, and copying works.
 */
import { test, expect } from '@playwright/test';
import { readFileSync } from 'node:fs';

const site = readFileSync(new URL('../src/content/site.ts', import.meta.url), 'utf8');
const pick = (key: string) => site.match(new RegExp(`${key}: '([^']+)'`))![1];
const serverName = pick('serverName');
const mcpUrl = pick('mcpUrl');
const isMock = /mock: true/.test(site);

/** The shell commands for adding the MCP server, by agent. */
const mcpCommands: Record<string, string> = {
  'Claude Code': `claude mcp add --transport http ${serverName} ${mcpUrl}`,
  Codex: `codex mcp add ${serverName} --url ${mcpUrl}`,
  OpenClaw: `openclaw mcp add ${serverName} --url ${mcpUrl} --transport streamable-http`,
  Hermes: `hermes mcp add ${serverName} --url ${mcpUrl}`,
  'Gemini CLI': `gemini mcp add --transport http ${serverName} ${mcpUrl}`,
};

test.use({ permissions: ['clipboard-read', 'clipboard-write'] });

test('the hero shows the MCP server URL, and it copies', async ({ page }) => {
  await page.goto('/');
  const hero = page.locator('.hero-get .quick');

  await expect(hero.locator('.cmd__text')).toHaveText(mcpUrl);
  await hero.getByRole('button', { name: 'Copy the MCP server URL' }).click();
  await expect(hero.getByText('Copied')).toBeVisible();
  expect(await page.evaluate(() => navigator.clipboard.readText())).toBe(mcpUrl);
});

test('the hero has nothing above the headline, and no buttons but Copy and How to use', async ({ page }) => {
  await page.goto('/');
  // No top bar, no menu, no logo, no call-to-action buttons: the headline comes first, and the
  // only controls are the Copy for the MCP server URL and the How to use beside it.
  await expect(page.locator('header, nav[aria-label="Sections"], .strip, .btn')).toHaveCount(0);
  const first = await page.locator('main').evaluate((main) => {
    const walker = document.createTreeWalker(main, NodeFilter.SHOW_TEXT);
    let node: Node | null;
    while ((node = walker.nextNode())) if (node.textContent?.trim()) return node.parentElement?.closest('h1, h2, h3, p, button, a, div')?.tagName;
    return null;
  });
  expect(first).toBe('H1');
  const controls = await page.locator('.hero-row, .hero-get .quick').locator('a, button, select').evaluateAll((els) =>
    els.map((el) => (el.hasAttribute('data-copy') ? 'copy' : el.hasAttribute('data-howto') ? 'howto' : el.tagName.toLowerCase())),
  );
  expect(controls).toEqual(['copy', 'howto']);
});

test('the hero and the end show the MCP server URL alone, with no instructions', async ({ page }) => {
  await page.goto('/');
  for (const block of ['.hero-get', '[data-night]']) {
    const install = page.locator(`${block} .quick`);
    await expect(install.locator('.cmd__text')).toHaveText(mcpUrl);
    // No switch, no agent menu and no notes: every agent's steps are behind How to use.
    await expect(install.locator('[role="tab"], select, p, label')).toHaveCount(0);
  }
  // Nothing on the page offers the skill or its CLI any more.
  await expect(page.locator('[role="tab"]')).toHaveCount(0);
  for (const text of await page.locator('.cmd__text').allTextContents()) expect(text).not.toMatch(/skills? (add|install)/);
});

test('every MCP line in the full panel is built from the one server name and URL', async ({ page }) => {
  await page.goto('/#how');
  const panel = page.locator('#how .install');

  for (const [agent, command] of Object.entries(mcpCommands)) {
    await panel.getByRole('button', { name: agent, exact: true }).click();
    await expect(panel.locator('[data-agent-panel]:not([hidden]) .cmd__text')).toHaveText(command);
  }

  // No command on the page carries a key: sign-in happens over OAuth the first time the agent connects.
  const all = await page.locator('.cmd__text').allTextContents();
  for (const text of all) expect(text).not.toMatch(/api[-_ ]?key|bearer|authorization/i);
});

test('How to use opens every agent’s steps, Claude and ChatGPT first, and closes', async ({ page }) => {
  await page.goto('/');
  for (const where of ['hero', 'final']) {
    const dialog = page.locator(`#${where}-howto`);
    await expect(dialog).toBeHidden();
    await page.locator(`[data-howto="${where}-howto"]`).click();
    await expect(dialog).toBeVisible();
    const agents = await dialog.locator('[data-agent]').allTextContents();
    expect(agents.slice(0, 2).map((a) => a.trim())).toEqual(['Claude', 'ChatGPT']);
    await expect(dialog.locator('[data-agent-panel]:not([hidden]) .cmd__text')).toHaveText(mcpUrl);
    await page.keyboard.press('Escape');
    await expect(dialog).toBeHidden();
  }
});

test('the steps show one at a time, the agent’s own and then the sign-in', async ({ page }) => {
  await page.goto('/');
  await page.locator('[data-howto="hero-howto"]').click();
  const claude = page.locator('#hero-howto [data-agent-panel="claude"]');
  const shown = claude.locator('[data-step]:not([hidden])');
  await expect(shown).toHaveCount(1);
  await expect(shown).toContainText('Customize');
  await expect(claude.locator('[data-step-prev]')).toBeDisabled();

  const total = await claude.locator('[data-step]').count();
  for (let i = 1; i < total; i++) await claude.locator('[data-step-next]').click();
  await expect(shown).toContainText('Allow');
  await expect(shown).toHaveCount(1);
  await expect(claude.locator('[data-step-next]')).toBeDisabled();
});

test('the agent chosen in How it works is remembered', async ({ page }) => {
  await page.goto('/#how');
  const panel = page.locator('#how .install');
  await panel.getByRole('button', { name: 'Hermes', exact: true }).click();

  await page.reload();
  await expect(panel.locator('[data-agent="hermes"]')).toHaveAttribute('aria-pressed', 'true');
  await expect(panel.locator('[data-agent-panel]:not([hidden]) .cmd__text')).toHaveText(mcpCommands.Hermes);
});

/**
 * The launch check from PLAN.md section 9: the commands printed on the page have to work.
 * Skipped while the names are mocks; once `install.mock` is false it talks to the real things.
 */
test('launch check: the MCP server answers', async ({ request }) => {
  test.skip(isMock, 'install names in content/site.ts are still mocks (install.mock = true)');

  // The MCP server: a plain initialize request with no token is turned away with a 401
  // that points the agent at the OAuth sign-in, which is how every agent gets in.
  const response = await request.post(mcpUrl, {
    headers: { 'Content-Type': 'application/json', Accept: 'application/json, text/event-stream' },
    data: {
      jsonrpc: '2.0',
      id: 1,
      method: 'initialize',
      params: { protocolVersion: '2025-06-18', capabilities: {}, clientInfo: { name: 'launch-check', version: '1.0.0' } },
    },
  });
  expect(response.status()).toBe(401);
  expect(response.headers()['www-authenticate']).toMatch(/resource_metadata=/i);
});

{
  "name": "nevos-brain",
  "type": "module",
  "version": "0.1.0",
  "private": true,
  "packageManager": "pnpm@10.7.0",
  "engines": {
    "node": "^22.12.0"
  },
  "scripts": {
    "dev": "astro dev",
    "build": "node --env-file-if-exists=.env scripts/trustmrr-mrr.mjs && astro build",
    "mrr": "node --env-file-if-exists=.env scripts/trustmrr-mrr.mjs",
    "preview": "astro preview",
    "astro": "astro",
    "test": "playwright test",
    "art": "python3 art/scripts/prepare.py"
  },
  "dependencies": {
    "@fontsource/caveat": "^5.3.0",
    "@fontsource/lato": "^5.3.0",
    "@fontsource/merriweather": "^5.3.0",
    "astro": "^7.3.5",
    "gsap": "^3.15.0"
  },
  "devDependencies": {
    "@playwright/test": "^1.63.0"
  },
  "pnpm": {
    "onlyBuiltDependencies": [
      "esbuild",
      "sharp"
    ]
  }
}

/**
 * Behaviour for the install blocks: the copy buttons everywhere, and, in the full panel in "How
 * it works", the choice of agent, which is remembered. The small blocks in the hero and at the
 * end are the MCP server's URL, its Copy, and a "How to use" button that opens the full panel
 * in a dialog.
 */

const AGENT_KEY = 'nevos-brain:agent';

function track(event: string, detail: Record<string, string>) {
  // Analytics hook. DataFast is wired in at launch; until then this is a no-op.
  (window as unknown as { datafast?: (e: string, d: Record<string, string>) => void }).datafast?.(event, detail);
}

/** The agent is chosen with a row of buttons in the full panel. */
function setupAgents(roots: HTMLElement[]) {
  const pick = (id: string) => {
    for (const root of roots) {
      const panels = [...root.querySelectorAll<HTMLElement>('[data-agent-panel]')];
      if (!panels.some((p) => p.dataset.agentPanel === id)) continue;
      for (const p of panels) p.hidden = p.dataset.agentPanel !== id;
      for (const b of root.querySelectorAll<HTMLButtonElement>('[data-agent]')) b.setAttribute('aria-pressed', String(b.dataset.agent === id));
      for (const menu of root.querySelectorAll<HTMLSelectElement>('[data-agent-select]')) menu.value = id;
    }
  };

  const choose = (id: string) => {
    pick(id);
    try {
      localStorage.setItem(AGENT_KEY, id);
    } catch {
      // private mode: the choice just isn't remembered
    }
  };

  for (const root of roots) {
    for (const b of root.querySelectorAll<HTMLButtonElement>('[data-agent]')) b.addEventListener('click', () => choose(b.dataset.agent!));
    for (const menu of root.querySelectorAll<HTMLSelectElement>('[data-agent-select]')) menu.addEventListener('change', () => choose(menu.value));
  }

  try {
    const saved = localStorage.getItem(AGENT_KEY);
    if (saved) pick(saved);
  } catch {
    // ignore
  }
}

function setupCopy() {
  document.addEventListener('click', async (e) => {
    const btn = (e.target as HTMLElement).closest<HTMLButtonElement>('[data-copy]');
    if (!btn) return;
    const label = btn.querySelector<HTMLElement>('[data-copy-label]');
    const value = btn.dataset.copy ?? '';
    let ok = true;
    try {
      await navigator.clipboard.writeText(value);
    } catch {
      ok = false;
    }
    btn.classList.toggle('is-copied', ok);
    window.setTimeout(() => btn.classList.remove('is-copied'), 1800);
    if (label) {
      label.textContent = ok ? 'Copied' : 'Press ⌘C';
      if (!ok) {
        // Clipboard blocked: select the text so a manual copy is one keystroke away.
        const text = btn.parentElement?.querySelector('.cmd__text');
        if (text) {
          const range = document.createRange();
          range.selectNodeContents(text);
          const sel = getSelection();
          sel?.removeAllRanges();
          sel?.addRange(range);
        }
      }
      window.setTimeout(() => (label.textContent = 'Copy'), 1800);
    }
    if (ok) track('copy', { what: btn.dataset.copyName ?? '' });
  });
}

/** "How to use": opens the dialog with every agent's steps. Esc closes it natively, so do a close button and a click on the backdrop. */
function setupHowto() {
  for (const btn of document.querySelectorAll<HTMLButtonElement>('[data-howto]')) {
    const dialog = document.getElementById(btn.dataset.howto!) as HTMLDialogElement | null;
    if (!dialog) continue;
    btn.addEventListener('click', () => {
      dialog.showModal();
      track('howto', { where: btn.dataset.howtoName ?? '' });
    });
    dialog.querySelector('[data-howto-close]')?.addEventListener('click', () => dialog.close());
    dialog.addEventListener('click', (e) => {
      if (e.target === dialog) dialog.close();
    });
  }
}

/** The install guides: one step at a time, with Back and Next. Without this script every step shows. */
function setupSteppers() {
  for (const stepper of document.querySelectorAll<HTMLElement>('[data-stepper]')) {
    const steps = [...stepper.querySelectorAll<HTMLElement>('[data-step]')];
    const nav = stepper.querySelector<HTMLElement>('[data-stepper-nav]')!;
    const prev = nav.querySelector<HTMLButtonElement>('[data-step-prev]')!;
    const next = nav.querySelector<HTMLButtonElement>('[data-step-next]')!;
    const dots = [...nav.querySelectorAll<HTMLElement>('.stepper__dots > span')];
    let at = 0;
    const show = (i: number) => {
      at = Math.max(0, Math.min(steps.length - 1, i));
      steps.forEach((s, j) => (s.hidden = j !== at));
      dots.forEach((d, j) => d.classList.toggle('is-on', j === at));
      prev.disabled = at === 0;
      next.disabled = at === steps.length - 1;
    };
    prev.addEventListener('click', () => show(at - 1));
    next.addEventListener('click', () => show(at + 1));
    nav.hidden = steps.length < 2;
    show(0);
  }
}

const roots = [...document.querySelectorAll<HTMLElement>('[data-install]')];
setupAgents(roots);
setupCopy();
setupHowto();
setupSteppers();

{
  "$schema": "https://railway.com/railway.schema.json",
  "build": {
    "builder": "RAILPACK"
  }
}

/**
 * The five 3D objects on the stage: the brain, and one object per ability.
 *
 * Object space: x = left/right, y = up, z = toward the viewer. Every model fits inside a
 * sphere of radius about 1.15, so they can share one camera.
 */
import { BRAIN, egg } from './brain-shape';
import { FOLDS } from './folds';
import { ball, box, icosphere, lathe, merge, move, prism, rotate, scale, torus, tube, type Geo, type Vec3 } from './geometry';

export { BRAIN };

export const WHITE: Vec3 = [1, 1, 1];
export const INK: Vec3 = [0.29, 0.29, 0.29];
export const PINK: Vec3 = [1, 0, 0.514];
export const GREY: Vec3 = [0.86, 0.86, 0.86];

/** What the fragment shader draws on a part's surface. */
export const PATTERN = { none: 0, folds: 1, leaves: 2, rings: 3 } as const;

export type Part = {
  geo: Geo;
  color: Vec3;
  pattern?: number;
  /** Flat facets instead of smooth shading: for boxes, fins and other hard-edged parts. */
  flat?: boolean;
  /** Set to false for small marks that are already ink, which need no outline of their own. */
  outline?: boolean;
  /**
   * Push the outline this far back (model units). Anything of the part's own surface within
   * that distance then hides it, so a lumpy part keeps the line around its silhouette without
   * a second, ragged line along every dip in it.
   */
  sink?: number;
  /** No shading: the colour is used as is. */
  unlit?: boolean;
  /** Always faces the camera instead of turning with the rest of the object. */
  billboard?: boolean;
};

export type Model = {
  parts: Part[];
  /** 'turn' spins all the way round. 'rock' swings from side to side, for things with a face. */
  motion: 'turn' | 'rock';
  /** A fixed lean, in degrees, applied after the spin. */
  tilt?: { x?: number; z?: number };
  /** How fast it moves relative to the brain. */
  rate: number;
};

// --- the brain ------------------------------------------------------------------------------

const smoothstep = (a: number, b: number, v: number) => {
  const t = Math.max(0, Math.min(1, (v - a) / (b - a)));
  return t * t * (3 - 2 * t);
};

/** Reshape a unit sphere, vertex by vertex. `shape` returns the new position and the pattern coordinate. */
function sculpt(level: number, shape: (x: number, y: number, z: number) => { p: Vec3; q: Vec3 }): Geo {
  const g = icosphere(level);
  g.dir = [...g.pos];
  for (let i = 0; i < g.pos.length; i += 3) {
    const s = shape(g.pos[i], g.pos[i + 1], g.pos[i + 2]);
    g.pos[i] = s.p[0];
    g.pos[i + 1] = s.p[1];
    g.pos[i + 2] = s.p[2];
    g.pat[i] = s.q[0];
    g.pat[i + 1] = s.q[1];
    g.pat[i + 2] = s.q[2];
  }
  return g;
}

/**
 * The baked fold pattern, carried from the sphere it was grown on to a sphere one level
 * finer: vertices the two share keep their value, each new one takes the mean of the two it
 * sits between, and a little smoothing rounds off the corners that leaves.
 */
function foldPattern(g: Geo): Float32Array {
  const raw = atob(FOLDS.data);
  const n = g.pos.length / 3;
  const coarse = raw.length;
  const near: number[][] = Array.from({ length: n }, () => []);
  for (let i = 0; i < g.idx.length; i += 3) {
    for (let k = 0; k < 3; k++) near[g.idx[i + k]].push(g.idx[i + ((k + 1) % 3)]);
  }
  let u = new Float32Array(n);
  for (let i = 0; i < coarse; i++) u[i] = ((raw.charCodeAt(i) << 24) >> 24) / 127;
  for (let i = coarse; i < n; i++) {
    const parents = near[i].filter((j) => j < coarse);
    u[i] = parents.reduce((sum, j) => sum + u[j], 0) / (parents.length || 1);
  }
  for (let pass = 0; pass < 2; pass++) {
    const next = new Float32Array(n);
    for (let i = 0; i < n; i++) {
      let sum = 0;
      for (const j of near[i]) sum += u[j];
      next[i] = 0.5 * u[i] + (0.5 * sum) / near[i].length;
    }
    u = next;
  }
  return u;
}

function cerebrum(): Geo {
  const g = icosphere(FOLDS.level + 1);
  const pattern = foldPattern(g);
  g.dir = [...g.pos];
  g.val = pattern;
  g.shade = [];
  for (let i = 0; i < g.pos.length; i += 3) {
    const y = g.pos[i + 1];
    const { p, n } = egg(g.pos[i], y, g.pos[i + 2]);
    // A fold is an arc in section. The pattern runs like a sine wave from groove to groove,
    // so its arcsine is how far across the fold this vertex is: 0 in the groove, 1 on the crest.
    // The groove has a narrow flat floor for the ink line to sit on; a knife-edge crease
    // would zigzag from triangle to triangle and chew the line up.
    const across = (2 / Math.PI) * Math.asin(Math.min(1, Math.abs(pattern[i / 3])));
    const up = Math.max(0, (across - BRAIN.folds.floor) / (1 - BRAIN.folds.floor));
    const fold = BRAIN.folds.depth * (1 - (1 - up) ** 2);
    // The fissure between the hemispheres, fading out underneath.
    const cleft = BRAIN.fissure.depth * Math.exp(-((p[0] / BRAIN.fissure.width) ** 2)) * smoothstep(-0.34, -0.08, y);
    const lift = fold - cleft;
    for (let k = 0; k < 3; k++) {
      g.pos[i + k] = p[k] + n[k] * lift;
      g.pat[i + k] = p[k];
    }
    g.shade.push(...n);
  }
  return g;
}

function cerebellum(): Geo {
  const { c, r, cleft } = BRAIN.cerebellum;
  return sculpt(4, (x, y, z) => {
    // Pinched in along the middle, more so toward the back, so it reads as two halves.
    const pinch = 1 - cleft * Math.exp(-((x / 0.22) ** 2)) * smoothstep(0.4, -0.6, z);
    const q: Vec3 = [c[0] + r[0] * x, c[1] + r[1] * y * pinch, c[2] + r[2] * z * pinch];
    return { p: q, q };
  });
}

function stem(): Geo {
  const { top, bottom, r } = BRAIN.stem;
  const length = Math.hypot(top[0] - bottom[0], top[1] - bottom[1], top[2] - bottom[2]);
  // A peg with a rounded end: a quarter circle closes the bottom.
  const profile: [number, number][] = [[r * 1.15, length]];
  for (let i = 0; i <= 6; i++) {
    const a = (i / 6) * (Math.PI / 2);
    profile.push([r * Math.cos(a), r - r * Math.sin(a)]);
  }
  const g = lathe(profile, 20);
  const lean = (Math.atan2(top[2] - bottom[2], top[1] - bottom[1]) * 180) / Math.PI;
  return move(rotate(g, 'x', lean), bottom);
}

function brain(): Model {
  return {
    motion: 'turn',
    rate: 1,
    parts: [
      { geo: cerebrum(), color: WHITE, pattern: PATTERN.folds },
      { geo: cerebellum(), color: WHITE, pattern: PATTERN.leaves },
      { geo: stem(), color: WHITE },
    ],
  };
}

// --- niche radar: a dish on a stand, with one pink blip at its focus ---------------------------

function radar(): Model {
  const dish = lathe(
    [
      [0, 0.06],
      [0.2, 0.085],
      [0.4, 0.16],
      [0.56, 0.27],
      [0.6, 0.315],
      [0.625, 0.3],
      [0.44, 0.13],
      [0.22, 0.03],
      [0, 0],
    ],
    48,
  );
  const feed = tube([0, 0.5, 0], [0, 0.06, 0], 0.022, 0.03, 8);
  const blip = ball(0.085, [0, 0.54, 0]);
  const aim = (g: Geo) => move(rotate(g, 'x', 52), [0, 0.02, 0.02], false);
  return {
    motion: 'turn',
    rate: 0.9,
    parts: [
      { geo: aim(dish), color: WHITE, pattern: PATTERN.rings },
      { geo: aim(feed), color: GREY },
      { geo: aim(blip), color: PINK },
      { geo: ball(0.12, [0, -0.04, -0.02]), color: WHITE },
      { geo: tube([0, -0.06, -0.02], [0, -0.74, 0], 0.06, 0.085, 14), color: WHITE },
      {
        geo: lathe(
          [
            [0, -0.72],
            [0.4, -0.72],
            [0.44, -0.78],
            [0.44, -0.84],
            [0, -0.84],
          ],
          40,
        ),
        color: WHITE,
      },
    ],
  };
}

// --- hype antenna: a small lattice mast with three pink signal arcs ------------------------------

function antenna(): Model {
  const top: Vec3 = [0, 0.3, 0];
  const legs: Geo[] = [];
  const braces: Geo[] = [];
  const foot = (i: number, t: number): Vec3 => {
    const a = (i / 3) * Math.PI * 2 + Math.PI / 6;
    const r = 0.36 * (1 - t) + 0.035 * t;
    return [r * Math.cos(a), -0.8 + t * 1.1, r * Math.sin(a)];
  };
  for (let i = 0; i < 3; i++) {
    legs.push(tube(foot(i, 1), foot(i, 0), 0.026, 0.04, 8));
    for (const t of [0.2, 0.47, 0.72]) braces.push(tube(foot(i, t), foot((i + 1) % 3, t), 0.02, 0.02, 6));
    // One diagonal per bay keeps it reading as a lattice from every side.
    braces.push(tube(foot(i, 0.2), foot((i + 1) % 3, 0.47), 0.016, 0.016, 6));
  }
  const arcs = [0.24, 0.4, 0.56].map((r) =>
    move(torus(r, 0.036, (42 * Math.PI) / 180, (138 * Math.PI) / 180, 28, 8), [top[0], top[1] + 0.06, top[2]]),
  );
  return {
    motion: 'turn',
    rate: 0.8,
    parts: [
      { geo: merge(...legs, ...braces), color: WHITE },
      { geo: ball(0.09, [0, top[1] + 0.06, 0]), color: WHITE },
      {
        geo: lathe(
          [
            [0, -0.78],
            [0.48, -0.78],
            [0.52, -0.83],
            [0.52, -0.88],
            [0, -0.88],
          ],
          40,
        ),
        color: WHITE,
      },
      { geo: merge(...arcs), color: PINK, billboard: true },
    ],
  };
}

// --- tactics board: a clipboard with a play drawn on it, the arrow in pink -----------------------

function tactics(): Model {
  const z = 0.062; // marks sit just proud of the paper
  const cross = (x: number, y: number) =>
    merge(
      move(rotate(box(0.2, 0.04, 0.012), 'z', 45), [x, y, z]),
      move(rotate(box(0.2, 0.04, 0.012), 'z', -45), [x, y, z]),
    );
  const nought = (x: number, y: number) => move(torus(0.075, 0.018, 0, Math.PI * 2, 24, 6), [x, y, z]);

  // The play: an arc from lower left sweeping up to the right, ending in an arrowhead.
  const R = 0.46;
  const centre: Vec3 = [0.3, -0.34, z];
  const from = (100 * Math.PI) / 180;
  const to = (172 * Math.PI) / 180;
  const arc = move(torus(R, 0.026, from, to, 24, 6), centre);
  const tip: [number, number] = [centre[0] + R * Math.cos(from), centre[1] + R * Math.sin(from)];
  const head = move(
    rotate(
      prism(
        [
          [0.11, 0],
          [-0.05, 0.085],
          [-0.05, -0.085],
        ],
        0.03,
      ),
      'z',
      8,
    ),
    [tip[0] + 0.03, tip[1], z],
  );

  return {
    motion: 'rock',
    rate: 1.1,
    tilt: { x: -8 },
    parts: [
      { geo: box(1.02, 1.32, 0.07), color: WHITE, flat: true },
      { geo: move(box(0.86, 1.08, 0.03), [0, -0.06, 0.04]), color: WHITE, flat: true },
      { geo: move(box(0.42, 0.16, 0.11), [0, 0.62, 0.035]), color: GREY, flat: true },
      { geo: move(torus(0.075, 0.022, 0, Math.PI * 2, 24, 6), [0, 0.75, 0.02]), color: GREY },
      {
        geo: merge(cross(-0.27, 0.16), cross(0.28, 0.3), cross(0.27, -0.4), nought(-0.04, 0.34), nought(-0.28, -0.37)),
        color: INK,
        unlit: true,
        outline: false,
      },
      { geo: merge(arc, head), color: PINK, unlit: true, outline: false },
    ],
  };
}

// --- growth engine: a rocket with a pink flame -----------------------------------------------------

function rocket(): Model {
  const body = lathe(
    [
      [0, 1.02],
      [0.07, 0.97],
      [0.17, 0.85],
      [0.26, 0.64],
      [0.315, 0.38],
      [0.33, 0.1],
      [0.32, -0.2],
      [0.285, -0.42],
      [0.235, -0.56],
      [0, -0.56],
    ],
    40,
  );
  const nozzle = lathe(
    [
      [0, -0.54],
      [0.17, -0.54],
      [0.225, -0.7],
      [0, -0.7],
    ],
    28,
  );
  const flame = lathe(
    [
      [0, -0.68],
      [0.17, -0.7],
      [0.24, -0.86],
      [0.18, -1.08],
      [0.07, -1.27],
      [0, -1.4],
    ],
    28,
  );
  const fin = () =>
    prism(
      [
        [0.24, -0.58],
        [0.62, -0.82],
        [0.64, -0.6],
        [0.29, -0.1],
      ],
      0.07,
    );
  const fins = [0, 120, 240].map((a) => rotate(fin(), 'y', a));
  const rim = (a: number) => rotate(move(torus(0.12, 0.036, 0, Math.PI * 2, 28, 8), [0, 0.3, 0.31]), 'y', a);
  const glass = (a: number) =>
    rotate(move(rotate(lathe([[0, 0.03], [0.1, 0.03], [0.1, 0], [0, 0]], 24), 'x', 90), [0, 0.3, 0.3]), 'y', a);
  const all = (g: Geo) => scale(move(g, [0, 0.14, 0]), [0.8, 0.8, 0.8]);
  return {
    motion: 'turn',
    rate: 1.3,
    tilt: { z: -24, x: 6 },
    parts: [
      { geo: all(body), color: WHITE },
      { geo: all(merge(...fins)), color: WHITE, flat: true },
      { geo: all(nozzle), color: GREY },
      { geo: all(merge(rim(30), rim(210))), color: WHITE },
      { geo: all(merge(glass(30), glass(210))), color: GREY, outline: false },
      { geo: all(flame), color: PINK },
    ],
  };
}

export type ModelName = 'brain' | 'radar' | 'antenna' | 'tactics' | 'rocket';

export const buildModels = (): Record<ModelName, Model> => ({
  brain: brain(),
  radar: radar(),
  antenna: antenna(),
  tactics: tactics(),
  rocket: rocket(),
});

/**
 * The brain in the hero can be picked up with a mouse (brain/hero.ts): dragged sideways it
 * turns, dragged up or down it tips, and let go it sits back up. Dragging it never scrolls the
 * page. On a touch screen it cannot be picked up at all: a swipe over it scrolls the page.
 */
import { test, expect, type Page } from '@playwright/test';

type HeroHook = { pose: () => { spun: number; tip: number; held: boolean } };

const pose = (page: Page) => page.evaluate(() => (window as unknown as { __hero: HeroHook }).__hero.pose());

async function ready(page: Page) {
  await page.goto('/', { waitUntil: 'networkidle' });
  await page.waitForSelector('[data-hero-brain].is-live');
}

/** The middle of the brain's drawing square, in the window. */
async function middle(page: Page) {
  const box = (await page.locator('[data-hero-brain] canvas').boundingBox())!;
  return { x: box.x + box.width / 2, y: box.y + box.height / 2, size: box.width };
}

test('dragging the brain turns it and tips it, and it sits back up when let go', async ({ page }) => {
  await ready(page);
  const scrolled = await page.evaluate(() => window.scrollY);
  const { x, y, size } = await middle(page);

  await page.mouse.move(x, y);
  await page.mouse.down();
  await page.mouse.move(x + size * 0.4, y, { steps: 10 });
  const across = await pose(page);
  expect(across.held).toBe(true);
  // A drag to the right turns its front to the right: a third of a turn for 40% of the square.
  expect(across.spun).toBeGreaterThan(0.25);
  expect(Math.abs(across.tip)).toBeLessThan(0.01);

  await page.mouse.move(x + size * 0.4, y + size * 0.15, { steps: 6 });
  const down = await pose(page);
  expect(down.tip).toBeGreaterThan(0.2);
  // Held still, it stays where the hand put it.
  await page.waitForTimeout(400);
  expect((await pose(page)).spun).toBeCloseTo(down.spun, 3);

  await page.waitForTimeout(150);
  await page.mouse.up();
  await expect.poll(async () => Math.abs((await pose(page)).tip), { timeout: 4000 }).toBeLessThan(0.01);
  expect((await pose(page)).held).toBe(false);

  expect(await page.evaluate(() => window.scrollY)).toBe(scrolled);
});

test('a flick keeps the brain spinning for a moment', async ({ page }) => {
  await ready(page);
  const { x, y, size } = await middle(page);
  await page.mouse.move(x - size * 0.2, y);
  await page.mouse.down();
  await page.mouse.move(x + size * 0.2, y, { steps: 4 });
  await page.mouse.up();
  const released = (await pose(page)).spun;
  await page.waitForTimeout(500);
  // It went on turning after the hand let go, the same way.
  expect((await pose(page)).spun).toBeGreaterThan(released + 0.05);
});

test.describe('on a phone', () => {
  test.use({ viewport: { width: 390, height: 780 }, hasTouch: true, isMobile: true });

  test('a swipe over the brain scrolls the page and never turns it', async ({ page }) => {
    await ready(page);
    const cdp = await page.context().newCDPSession(page);
    const { x, y } = await middle(page);

    /** A finger on the middle of the brain, moved by (dx, dy) over 10 steps, then lifted. */
    const swipe = async (dx: number, dy: number) => {
      await cdp.send('Input.dispatchTouchEvent', { type: 'touchStart', touchPoints: [{ x, y }] });
      for (let i = 1; i <= 10; i++) {
        await cdp.send('Input.dispatchTouchEvent', { type: 'touchMove', touchPoints: [{ x: x + (dx * i) / 10, y: y + (dy * i) / 10 }] });
        await page.waitForTimeout(16);
      }
      await cdp.send('Input.dispatchTouchEvent', { type: 'touchEnd', touchPoints: [] });
      await page.waitForTimeout(300);
    };
    const scrollY = () => page.evaluate(() => window.scrollY);

    // Sideways: the brain is not picked up.
    await swipe(140, 0);
    expect(await pose(page)).toMatchObject({ spun: 0, held: false });

    // Up, and up and to one side: the page scrolls, as it does anywhere else.
    let before = await scrollY();
    await swipe(0, -220);
    expect(await scrollY()).toBeGreaterThan(before + 80);
    before = await scrollY();
    await page.evaluate(() => window.scrollTo(0, 0));
    await page.waitForTimeout(200);
    await swipe(120, -200);
    expect(await scrollY()).toBeGreaterThan(60);
    expect(await pose(page)).toMatchObject({ spun: 0, held: false });

    // The browser handles every touch on it: nothing on the brain overrides that.
    expect(await page.locator('[data-hero-brain] canvas').evaluate((c) => getComputedStyle(c).touchAction)).toBe('auto');
  });
});

/**
 * Nevo's scenes at the bottom of the ability sections (components/NevoAct.astro): each is a
 * video that the scroll plays. These check that where a scene is on the screen is where its
 * video is, both ways, that the mouse does nothing to it, and that it stays a still for someone
 * who asked for less motion.
 */
import { test, expect, type Page } from '@playwright/test';

async function ready(page: Page) {
  await page.goto('/', { waitUntil: 'networkidle' });
  await page.evaluate(() => document.fonts.ready);
}

/** Where the scene's video is, from 0 (its first frame) to 1 (its last). */
const position = (page: Page, act: string) =>
  page.evaluate((act) => {
    const v = document.querySelector<HTMLVideoElement>(`[data-act="${act}"] video`)!;
    return v.currentTime / v.duration;
  }, act);

/**
 * The scroll positions at which the scene starts and ends: it starts with nearly all of the
 * picture on screen, and has played out when the picture is in the middle of the screen.
 */
async function span(page: Page, act: string) {
  return page.evaluate((act) => {
    const box = document.querySelector(`[data-act="${act}"]`)!.getBoundingClientRect();
    const bottom = box.bottom + window.scrollY;
    const view = window.innerHeight;
    return {
      // Its bottom a little below the bottom of the screen.
      start: Math.round(bottom - view - box.height * 0.15),
      // Its middle at the middle of the screen.
      end: Math.round(bottom - view / 2 - box.height / 2),
      view,
    };
  }, act);
}

const scrollTo = (page: Page, y: number) => page.evaluate((y) => window.scrollTo(0, y), y);

/** Brings a scene near and waits until its video can be played. */
async function load(page: Page, act: string) {
  const { start } = await span(page, act);
  await scrollTo(page, start);
  await page.waitForSelector(`[data-act="${act}"].is-live`, { timeout: 15_000 });
}

for (const act of ['scan', 'surf', 'coach', 'grow']) {
  test(`the scroll plays the ${act} scene, both ways`, async ({ page }) => {
    await ready(page);
    await load(page, act);
    const { start, end, view } = await span(page, act);
    // Quick, but not so quick it is missed: about a third of a screen of scrolling.
    expect(end - start).toBeGreaterThan(view * 0.3);
    expect(end - start).toBeLessThan(view * 0.45);

    await scrollTo(page, start - 80);
    await expect.poll(() => position(page, act), { timeout: 5000 }).toBeLessThan(0.03);

    await scrollTo(page, Math.round((start + end) / 2));
    await expect.poll(() => position(page, act), { timeout: 5000 }).toBeGreaterThan(0.4);
    await expect.poll(() => position(page, act), { timeout: 5000 }).toBeLessThan(0.6);

    await scrollTo(page, end + 80);
    await expect.poll(() => position(page, act), { timeout: 5000 }).toBeGreaterThan(0.97);

    // Played out, the picture is still whole on screen, and stays so a while longer.
    for (const y of [end, end + Math.round(view * 0.15)]) {
      await scrollTo(page, y);
      const box = await page.evaluate((act) => document.querySelector(`[data-act="${act}"]`)!.getBoundingClientRect().toJSON(), act);
      expect(box.top, `the top of the picture, at ${y}`).toBeGreaterThanOrEqual(0);
      expect(box.bottom, `the bottom of the picture, at ${y}`).toBeLessThanOrEqual(view);
    }

    // Back up: it runs backwards.
    await scrollTo(page, Math.round(start + (end - start) * 0.25));
    await expect.poll(() => position(page, act), { timeout: 5000 }).toBeGreaterThan(0.15);
    await expect.poll(() => position(page, act), { timeout: 5000 }).toBeLessThan(0.35);
  });
}

test('the mouse does nothing to a scene, and the page does not move', async ({ page }) => {
  await ready(page);
  await load(page, 'scan');
  const { start, end } = await span(page, 'scan');
  await scrollTo(page, Math.round((start + end) / 2));
  // Settled: it eases toward where the scroll says, so wait until it has stopped.
  let previous = -1;
  await expect
    .poll(
      async () => {
        const now = await position(page, 'scan');
        const still = now === previous;
        previous = now;
        return still;
      },
      { timeout: 5000, intervals: [200] },
    )
    .toBe(true);
  const before = await position(page, 'scan');

  const viewport = page.viewportSize()!;
  await page.mouse.move(viewport.width * 0.05, viewport.height * 0.7, { steps: 4 });
  await page.mouse.move(viewport.width * 0.95, viewport.height * 0.2, { steps: 8 });
  await page.waitForTimeout(600);

  expect(await position(page, 'scan')).toBeCloseTo(before, 2);
  expect(await page.evaluate(() => window.scrollY)).toBe(Math.round((start + end) / 2));
});

test('with reduced motion, the scenes stay stills and load no video', async ({ page }) => {
  await page.emulateMedia({ reducedMotion: 'reduce' });
  await ready(page);
  await page.evaluate(() => document.querySelector('[data-act="scan"]')!.scrollIntoView({ block: 'center' }));
  await page.waitForTimeout(1500);
  const state = await page.evaluate(() =>
    [...document.querySelectorAll<HTMLElement>('[data-act]')].map((el) => ({
      live: el.classList.contains('is-live'),
      src: el.querySelector('video')?.getAttribute('src') ?? null,
    })),
  );
  expect(state.length).toBe(4);
  expect(state.every((s) => !s.live && !s.src)).toBe(true);
});

/**
 * The scroll rules from PLAN.md 6.1, as tests. The brain story is scroll-linked, and these
 * make sure it stays that way without ever touching how the page scrolls:
 * no changed speed, no pinned sections, no scrolling that doesn't move the page.
 */
import { test, expect, type Page } from '@playwright/test';

type StageHook = {
  marks: () => { gatherFrom: number; gatherTo: number; landingFrom: number; landingTo: number };
  state: () => Record<string, number>;
  settled: () => boolean;
};

/**
 * Waits until the stage has caught up with the scroll position: its eased time has reached
 * the target, and nothing it sets is still changing.
 */
async function settle(page: Page) {
  await expect
    .poll(() => page.evaluate(() => (window as unknown as { __stage: StageHook }).__stage.settled()), { timeout: 8000, intervals: [100] })
    .toBe(true);
  let previous = '';
  await expect
    .poll(
      async () => {
        const now = await signature(page);
        const stable = now === previous;
        previous = now;
        return stable;
      },
      { timeout: 6000, intervals: [250] },
    )
    .toBe(true);
}

async function ready(page: Page) {
  await page.goto('/', { waitUntil: 'networkidle' });
  await page.evaluate(() => document.fonts.ready);
  await page.waitForSelector('[data-hero-brain].is-live');
}


/**
 * A snapshot of everything the scroll story sets, to compare states: the values the timeline
 * writes (transforms, opacity, the scene's numbers), rounded. It deliberately reads those
 * rather than where things are on screen, because Nevo also breathes, blinks and looks about
 * on a timer.
 */
const signature = (page: Page) =>
  page.evaluate(() => {
    const round = (text: string) => text.replace(/-?\d+\.\d+/g, (n) => String(Math.round(Number(n) * 10) / 10));
    const read = (sel: string) =>
      [...document.querySelectorAll<HTMLElement | SVGElement>(sel)].map((el) =>
        round([el.style.transform, el.getAttribute('transform') ?? '', el.style.opacity, el.style.strokeDashoffset].join('|')),
      );
    const scene = document.querySelector<HTMLElement>('[data-scene]')!;
    const state = (window as unknown as { __stage: StageHook }).__stage.state();
    return JSON.stringify({
      scene: round(['--hero', '--final', '--rise'].map((v) => scene.style.getPropertyValue(v)).join('|')),
      numbers: Object.values(state).map((v) => Math.round(v * 100) / 100),
      brain: read('[data-brain]'),
      nodes: read('[data-node]'),
      links: read('[data-link], [data-ring]'),
      bust: read('[data-bust]'),
      head: read('[data-head], [data-face], [data-bust-nose]'),
      lid: read('[data-lid]'),
      face: read('[data-bust-eye], [data-bust-brow], [data-bust-mouth], [data-bust-oh]'),
      callout: read('[data-callout]'),
    });
  });

test('the wheel scrolls exactly as far as it is turned', async ({ page }) => {
  await ready(page);
  await page.mouse.move(400, 500);
  for (const delta of [300, 700, 1200]) {
    const before = await page.evaluate(() => window.scrollY);
    await page.mouse.wheel(0, delta);
    await expect.poll(() => page.evaluate(() => window.scrollY), { timeout: 5000 }).toBe(before + delta);
  }
});

test('nothing listens to the wheel, and touch listeners are passive', async ({ page }) => {
  await page.addInitScript(() => {
    const log: { type: string; passive: boolean; from: string }[] = [];
    (window as unknown as { __listeners: typeof log }).__listeners = log;
    const original = EventTarget.prototype.addEventListener;
    EventTarget.prototype.addEventListener = function (type, listener, options) {
      const passive = typeof options === 'object' && options !== null && options.passive === true;
      const from = (new Error().stack ?? '').split('\n')[2]?.trim() ?? '';
      log.push({ type, passive, from });
      return original.call(this, type, listener, options);
    };
  });
  await ready(page);
  const listeners = await page.evaluate(
    () => (window as unknown as { __listeners: { type: string; passive: boolean; from: string }[] }).__listeners,
  );

  const wheel = listeners.filter((l) => ['wheel', 'mousewheel', 'DOMMouseScroll'].includes(l.type));
  expect(wheel, 'no wheel listeners anywhere').toEqual([]);

  // Playwright adds a touchstart listener of its own from an injected script; only listeners
  // added by the page's code (loaded over http) count.
  const touch = listeners.filter(
    (l) => ['touchstart', 'touchmove'].includes(l.type) && !l.passive && /https?:\/\//.test(l.from),
  );
  expect(touch, 'no touch listener that could block scrolling').toEqual([]);

  const inline = await page.evaluate(() => document.querySelectorAll('[onwheel], [ontouchmove]').length);
  expect(inline).toBe(0);

  const css = await page.evaluate(() => {
    const html = getComputedStyle(document.documentElement);
    const body = getComputedStyle(document.body);
    return { behavior: html.scrollBehavior, snapHtml: html.scrollSnapType, snapBody: body.scrollSnapType };
  });
  expect(css).toEqual({ behavior: 'auto', snapHtml: 'none', snapBody: 'none' });
});

test('inside the story, text moves one pixel for every pixel scrolled', async ({ page }) => {
